package com.oguzguven.portfolio.message;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ContactMessageService{private final ContactMessageRepository repository;public ContactMessageService(ContactMessageRepository repository){this.repository=repository;}@Transactional public ContactMessageResponse create(ContactMessageRequest request){return ContactMessageResponse.from(repository.save(new ContactMessage(request)));}@Transactional(readOnly=true)public List<ContactMessageResponse> findAll(){return repository.findAllByOrderByCreatedAtDesc().stream().map(ContactMessageResponse::from).toList();}@Transactional public ContactMessageResponse toggleRead(UUID id){var value=repository.findById(id).orElseThrow(()->new NoSuchElementException("Mesaj bulunamadı."));value.toggleRead();return ContactMessageResponse.from(value);}@Transactional public void delete(UUID id){if(!repository.existsById(id))throw new NoSuchElementException("Mesaj bulunamadı.");repository.deleteById(id);}}
